def mk(kind):
    def res(p):
        c,e,k,pw=p[0],p[1],p[2],p[3]
        if kind==0: X=t**pw*np.exp(-e*t)*A**k
        elif kind==1: X=t**pw*np.exp(-e*A)*A**k
